-- sorel_page — export table article pour Aiven
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `article`;
CREATE TABLE `article` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `description` varchar(255) DEFAULT NULL,
  `reference` varchar(100) DEFAULT NULL,
  `conditionnement` varchar(100) DEFAULT NULL,
  `dimensions` varchar(100) DEFAULT NULL,
  `contenance_ml` varchar(100) DEFAULT NULL,
  `process_de_cuisson` varchar(255) DEFAULT NULL,
  `versage_a_chaud` varchar(50) DEFAULT NULL,
  `forme` varchar(100) DEFAULT NULL,
  `avec_couvercle` varchar(50) DEFAULT NULL,
  `couleur` varchar(100) DEFAULT NULL,
  `cent_pourcent_recyclable` varchar(50) DEFAULT NULL,
  `operculable` varchar(50) DEFAULT NULL,
  `modulables` varchar(50) DEFAULT NULL,
  `personnalisables` varchar(50) DEFAULT NULL,
  `famille_forme` varchar(100) DEFAULT NULL,
  `autre_famille` varchar(100) DEFAULT NULL,
  `produit_associe_1` varchar(255) DEFAULT NULL,
  `produit_associe_2` varchar(255) DEFAULT NULL,
  `produit_associe_3` varchar(255) DEFAULT NULL,
  `produit_associe_4` varchar(255) DEFAULT NULL,
  `valeur_ajoutee_1` text DEFAULT NULL,
  `valeur_ajoutee_2` text DEFAULT NULL,
  `valeur_ajoutee_3` text DEFAULT NULL,
  `valeur_ajoutee_4` text DEFAULT NULL,
  `valeur_cial` text DEFAULT NULL,
  `gamme` varchar(100) DEFAULT NULL,
  `photo` varchar(500) DEFAULT NULL,
  `photo_produit_ass1` varchar(500) DEFAULT NULL,
  `photo_produit_ass2` varchar(500) DEFAULT NULL,
  `photo_produit_ass3` varchar(500) DEFAULT NULL,
  `photo_produit_ass4` varchar(500) DEFAULT NULL,
  `photo_gamme` varchar(500) DEFAULT NULL,
  `Column33` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_article_gamme` (`gamme`)
) ENGINE=InnoDB AUTO_INCREMENT=226 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;






SET FOREIGN_KEY_CHECKS = 1;